import os, re, datetime

LOG_DIR = '/app/logs'
ref = datetime.date(2025, 8, 12)
periods = {
    'today': (ref, ref),
    'last_7_days': (ref - datetime.timedelta(days=6), ref),
    'last_30_days': (ref - datetime.timedelta(days=29), ref),
    'month_to_date': (ref.replace(day=1), ref),
}
order = ['today', 'last_7_days', 'last_30_days', 'month_to_date', 'total']
sevs = ['ERROR', 'WARNING', 'INFO']
counts = {p: {s: 0 for s in sevs} for p in order}
file_re = re.compile(r'^(\d{4})-(\d{2})-(\d{2})_.+\.log$')
valid = {'[ERROR]': 'ERROR', '[WARNING]': 'WARNING', '[INFO]': 'INFO'}

for name in sorted(os.listdir(LOG_DIR)):
    if not os.path.isfile(os.path.join(LOG_DIR, name)):
        continue
    m = file_re.match(name)
    if not m:
        continue
    d = datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    active = [p for p, (start, end) in periods.items() if start <= d <= end]
    with open(os.path.join(LOG_DIR, name), 'r', encoding='utf-8', errors='replace') as f:
        for line in f:
            parts = line.split(None, 3)
            if len(parts) < 3:
                continue
            sev = valid.get(parts[2])
            if sev is None:
                continue
            counts['total'][sev] += 1
            for p in active:
                counts[p][sev] += 1

with open('/app/summary.csv', 'w', encoding='utf-8', newline='\n') as f:
    f.write('period,severity,count\n')
    for p in order:
        for s in sevs:
            f.write(f'{p},{s},{counts[p][s]}\n')

print('Wrote /app/summary.csv')
